const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n)+' ₽';
const count=(n,one,few,many)=>`${n} ${n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many}`;
const photoLabel=n=>count(n,'фотография','фотографии','фотографий');
const statuses={pending:'В очереди',processing:'Обработка',no_face:'Лицо не найдено',multiple_faces:'Несколько лиц',small_face:'Лицо слишком маленькое',error:'Ошибка обработки',ready:'Готово'};
const STAGES=[['new','Загрузить фото','#7712b3','#fff','Классы, где съёмка прошла, а фотографии ещё не загружены.'],['photos','Проверить фото','#4d6ff0','#fff','Проверьте группы портретов и отправьте классу анкеты.'],['forms','Сбор данных','#50b7f1','#0b2a3d','Класс заполняет анкеты детей и выбирает учителей. Перед созданием макета проверьте состав.'],['layout','Сверстать макет','#28cec5','#063a37','Проверьте собранный макет и отправьте его классу на согласование.'],['approval','Согласовать макет','#f29b38','#3d2200','Макет у класса. После согласования отправьте заказ в печать.'],['print','Напечатать','#e2458a','#fff','Заказы в типографии. Отметьте, когда альбомы переданы в доставку.'],['delivery','Доставить','#3aa655','#fff','Альбомы едут к классу. После выдачи перенесите заказ в архив.'],['archive','Архив','#8a8b85','#fff','Завершённые заказы.']];
const stageOf=key=>STAGES.find(s=>s[0]===key)||STAGES[0];
const stageLabel=key=>stageOf(key)[1];
const daysIn=o=>Math.max(0,Math.floor((Date.now()-Date.parse(o.stage_at||o.created_at))/864e5));
// The photographer's move: work inside the stage, a finished stage to pass on, or a class gone quiet to remind.
const isMine=st=>st.kind==='todo'||st.kind==='done'||!!st.stale;
const LEGACY_STAGES={planned:'new',scheduled:'new',upload:'photos'};
const withStage=o=>{if(!STAGES.some(s=>s[0]===o.stage))o.stage=LEGACY_STAGES[o.stage]||'new';return o;};
const fmtDate=d=>String(d||'').split('-').reverse().join('.');
let toastTimer,pollTimer,routeVersion=0,groupsSig='';
async function api(path,options={}){const r=await fetch('/api'+path,options);let value=await r.json();if(!r.ok)throw Error(typeof value.detail==='string'?value.detail:'Проверьте заполнение полей');return value;}
function json(method,body){return {method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)};}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function schoolLabel(o){return `${o.school}${o.school_city?` · ${o.school_city}`:''}`;}
function schoolFilterKey(o){return o.school_id||schoolLabel(o);}
function orderName(o){return `${schoolLabel(o)} / ${o.class_name}`;}
function personName(p,index){return p.name||`Персона ${String(index+1).padStart(2,'0')}`;}
function defaultGraduationYear(date=new Date()){return date.getFullYear()+(date.getMonth()>=8?1:0);}
function packageMeta(p){const s=p.summary||{},parts=[];if(s.spreads)parts.push(count(s.spreads,'разворот','разворота','разворотов'));if(s.page_size)parts.push(`${s.page_size[0]}×${s.page_size[1]}`);return parts.join(' · ');}
function packageCover(d,i){return `<span class="package-thumb cover-${i%3}"><span class="mini-book"><span><small>ALBUM FACTORY</small><strong>${esc(d.name)}</strong></span><span class="mini-art"><i></i><i></i><i></i></span></span></span>`;}
function packageRow(item){return item.package?`${packageCover(item.design,item.index)}<span class="package-text"><strong>${esc(item.package.name)}</strong><small>${esc([item.design.name,packageMeta(item.package)].filter(Boolean).join(' · '))}</small></span><b class="package-price">${money(item.package.price)}</b>`:`<span class="package-thumb later">${svgIcon(item.later?'clock':'layout',18)}</span><span class="package-text"><strong>${item.later?'Выбрать позже':'Выберите комплектацию'}</strong><small>${item.later?'Цену возьмём из комплектации при создании макета':'Цена альбома берётся из комплектации'}</small></span>`;}
function packagePicker(designs,selected='',optional=true){const items=designs.flatMap((design,index)=>design.packages.map(p=>({design,index,package:p}))),current=items.find(x=>x.package.template_id===selected),empty={later:optional};const option=(item,value)=>`<button type="button" role="option" class="package-item" data-package="${esc(value)}" aria-selected="${value===(current?selected:'')}">${packageRow(item)}</button>`;const list=(optional?option(empty,''):'')+designs.map((d,i)=>d.packages.length?`<div class="package-group" role="group" aria-label="${esc(d.name)}"><h3>${esc(d.name)}</h3>${d.packages.map(p=>option({design:d,index:i,package:p},p.template_id)).join('')}</div>`:'').join('');return `<div class="package-select"><input type="hidden" name="master_template_id" value="${esc(current?selected:'')}"><button type="button" class="package-trigger" aria-haspopup="listbox" aria-expanded="false">${packageRow(current||empty)}${svgIcon('chevron',18)}</button><div class="package-list" role="listbox" hidden>${list||''}${items.length?'':`<p class="package-empty muted">Пока нет комплектаций. Создайте дизайн в разделе <a href="#masters">«Мастер-макеты»</a>.</p>`}</div></div>`;}
function placePackageList(root){const list=root.querySelector('.package-list'),box=root.querySelector('.package-trigger').getBoundingClientRect(),below=innerHeight-box.bottom-16,above=box.top-16,up=below<280&&above>below,max=Math.min(360,up?above:below);list.style.left=box.left+'px';list.style.width=box.width+'px';list.style.maxHeight=max+'px';list.style.top=up?'':box.bottom+6+'px';list.style.bottom=up?innerHeight-box.top+6+'px':'';}
function togglePackages(root,open){const list=root.querySelector('.package-list'),trigger=root.querySelector('.package-trigger');list.hidden=!open;trigger.setAttribute('aria-expanded',String(open));root.classList.toggle('open',open);if(open){placePackageList(root);(list.querySelector('[aria-selected="true"]')||list.querySelector('.package-item'))?.focus();}}
function choosePackage(item){const root=item.closest('.package-select');root.querySelector('input').value=item.dataset.package;root.querySelectorAll('.package-item').forEach(x=>x.setAttribute('aria-selected',String(x===item)));root.querySelector('.package-trigger').innerHTML=item.innerHTML+svgIcon('chevron',18);togglePackages(root,false);root.querySelector('.package-trigger').focus();root.querySelector('input').dispatchEvent(new Event('change',{bubbles:true}));}
document.addEventListener('click',e=>{const trigger=e.target.closest('.package-trigger'),item=e.target.closest('.package-item');if(trigger){const root=trigger.closest('.package-select');togglePackages(root,root.querySelector('.package-list').hidden);}else if(item)choosePackage(item);});
document.addEventListener('pointerdown',e=>{document.querySelectorAll('.package-select.open').forEach(root=>{if(!root.contains(e.target))togglePackages(root,false);});},true);
document.addEventListener('keydown',e=>{const root=e.target.closest?.('.package-select');if(!root)return;const open=root.classList.contains('open');if(e.key==='Escape'&&open){e.preventDefault();e.stopPropagation();togglePackages(root,false);root.querySelector('.package-trigger').focus();return;}if(!['ArrowDown','ArrowUp'].includes(e.key))return;e.preventDefault();if(!open){togglePackages(root,true);return;}const items=[...root.querySelectorAll('.package-item')],at=items.indexOf(document.activeElement);items[(at+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();},true);
document.addEventListener('scroll',e=>{document.querySelectorAll('.package-select.open').forEach(root=>{if(!root.contains(e.target))togglePackages(root,false);});},true);
addEventListener('resize',()=>document.querySelectorAll('.package-select.open').forEach(placePackageList));
async function schoolChoices(){const saved=await api('/schools'),known=new Set(saved.map(s=>searchKey(s.name)));const legacy=[...new Set(state.orders.map(o=>o.school).filter(Boolean))].filter(n=>!known.has(searchKey(n))).map(name=>({id:'',name}));return [...saved,...legacy].sort((a,b)=>a.name.localeCompare(b.name,'ru'));}
function schoolPicker(root,list,current=null){
  const listId=root.id+'-options';let chosen=current,active=0;
  root.innerHTML=`<label>Название школы <i class="req" aria-hidden="true">*</i><input name="school" maxlength="300" required role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${listId}" placeholder="Найдите или введите название школы" autocomplete="off" value="${esc(current?.name||'')}"></label><ul class="school-options" id="${listId}" role="listbox" hidden></ul><label>Город <i class="req" aria-hidden="true">*</i><input name="school_city" maxlength="100" required autocomplete="address-level2" placeholder="Например, Казань" value="${esc(current?.city||'')}"></label><input type="hidden" name="school_id" value="${esc(current?.id||'')}"><p class="muted small">Название и город сохранятся вместе в каталоге. Город доступен для текста на обложке.</p><p class="school-error error" role="alert"></p>`;
  const name=root.querySelector('[name=school]'),city=root.querySelector('[name=school_city]'),id=root.querySelector('[name=school_id]'),ul=root.querySelector('ul');
  const options=()=>name.value.trim()?list.filter(s=>(!name.value||searchKey(s.name).includes(searchKey(name.value)))&&(!city.value||!s.city||searchKey(s.city).includes(searchKey(city.value)))):[];
  const close=()=>{ul.hidden=true;name.setAttribute('aria-expanded','false');name.removeAttribute('aria-activedescendant');};
  const pick=s=>{chosen=s;name.value=s.name;city.value=s.city||city.value;id.value=s.id||'';close();city.focus();};
  const draw=()=>{const items=options();active=Math.max(0,Math.min(active,items.length-1));ul.hidden=false;name.setAttribute('aria-expanded','true');ul.innerHTML=items.map((s,i)=>`<li role="option" data-i="${i}" id="${listId}-${i}" class="${i===active?'active':''}" aria-selected="${i===active}"><span>${esc(s.name)}<small> · ${esc(s.city||'Укажите город')}</small></span></li>`).join('')||'<li class="empty">Новая школа — добавится при сохранении</li>';name.setAttribute('aria-activedescendant',items.length?`${listId}-${active}`:'');ul.onmousedown=e=>e.preventDefault();ul.onclick=e=>{const li=e.target.closest('[data-i]');if(li)pick(items[+li.dataset.i]);};};
  name.oninput=()=>{chosen=null;id.value='';active=0;if(name.value.trim())draw();else close();};name.onblur=close;
  city.oninput=()=>{if(chosen?.city&&searchKey(city.value)!==searchKey(chosen.city)){chosen=null;id.value='';}};
  name.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();active+=e.key==='ArrowDown'?1:-1;draw();}else if(e.key==='Enter'&&!ul.hidden){e.preventDefault();const item=options()[active];if(item)pick(item);else{close();city.focus();}}else if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();}};
  return {get value(){return {id:id.value,name:name.value.trim(),city:city.value.trim()};}};
}
let orderSchool=null;
async function openNew(selectedSchool=null){$('#order-form').reset();$('#graduation-year').value=defaultGraduationYear();$('#form-error').textContent='';const packages=$('#order-packages'),school=$('#order-school');packages.innerHTML='<p class="muted small">Загружаем комплектации…</p>';school.innerHTML='<p class="muted small">Загружаем школы…</p>';orderSchool=null;$('#order-dialog').showModal();const [schools,designs]=await Promise.allSettled([schoolChoices(),api('/designs')]);if(!$('#order-dialog').open)return;orderSchool=schoolPicker(school,schools.value||[],selectedSchool);if(schools.status==='rejected')$('#form-error').textContent='Не удалось загрузить школы. Новую школу можно создать здесь же.';packages.innerHTML=designs.status==='fulfilled'?packagePicker(designs.value):'<p class="error">Не удалось загрузить мастер-макеты. Можно создать заказ и выбрать комплектацию позже.</p>'+packagePicker([]);school.querySelector('input')?.focus();}
function chooseOrderMaster(){return LayoutStart.open();}

// Dashboard and order registry share the same status model as the stage queues.
const orderFilters={query:'',school:'',className:'',stage:'',scope:'all',attention:false};
const searchKey=value=>String(value||'').toLocaleLowerCase('ru').replace(/ё/g,'е').replace(/[\s«»"№/·-]/g,'');
// Orders waiting for the photographer come first; inside each group schools and classes go in natural order (№ 5 before № 20, 9 Б before 10 А).
const orderSort=(a,b)=>isMine(cardStatus(b))-isMine(cardStatus(a))||schoolLabel(a).localeCompare(schoolLabel(b),'ru',{numeric:true})||String(a.class_name||'').localeCompare(String(b.class_name||''),'ru',{numeric:true});
function registryOrders({ignoreStage=false}={}){const f=orderFilters,q=searchKey(f.query);return state.orders.filter(o=>(!q||searchKey([o.school,o.school_city,o.class_name,o.customer_name,o.customer_contact].join(' ')).includes(q))&&(!f.school||schoolFilterKey(o)===f.school||o.school===f.school)&&(!f.className||searchKey(o.class_name)===searchKey(f.className))&&(ignoreStage||!f.stage||o.stage===f.stage)&&((f.scope==='archive'?o.stage==='archive':f.scope==='waiting'?['forms','approval'].includes(o.stage)&&cardStatus(o).kind==='waiting':o.stage!=='archive'))&&(!f.attention||isMine(cardStatus(o)))).sort(orderSort);}
let registryView;
function ordersView(){if(registryView)return registryView;try{return localStorage.getItem('ordersView')==='board'?'board':'grid';}catch{return 'grid';}}
function ordersPage(params=new URLSearchParams()){if(params.size){Object.assign(orderFilters,{query:params.get('q')||'',school:params.get('school')||'',className:params.get('class')||'',stage:params.get('stage')||'',scope:params.get('scope')||'all',attention:params.get('attention')==='1'});}const f=orderFilters,view=ordersView();const schools=[...new Map(state.orders.map(o=>[schoolFilterKey(o),o])).values()].sort((a,b)=>schoolLabel(a).localeCompare(schoolLabel(b),'ru',{numeric:true})).map(o=>[schoolFilterKey(o),schoolLabel(o)]),classes=[...new Map(state.orders.map(o=>[searchKey(o.class_name),o.class_name])).values()].sort((a,b)=>a.localeCompare(b,'ru',{numeric:true})).map(v=>[v,v]);const chip=(key,ico,label,options,selected)=>`<span class="filter-chip" data-chip="${key}">${svgIcon(ico,15)}<span class="chip-label">${label}</span><select id="filter-${key}" aria-label="${label}"><option value="" data-menu-label="${{school:'Все школы',class:'Все классы',stage:'Все этапы'}[key]}">${label}</option>${options.map(([v,text,color])=>`<option value="${esc(v)}" ${color?`data-color="${color}"`:''} ${selected(v)?'selected':''}>${esc(text)}</option>`).join('')}</select><button type="button" class="chip-clear" data-clear="${key}" aria-label="Сбросить: ${label}">×</button></span>`;$('#main').innerHTML=`<div class="page registry"><div class="queue-head"><div><h1>Все заказы</h1><p class="muted">Школы, классы и состояние каждого заказа</p></div><div class="queue-tools"><label class="queue-search ${f.query?'open':''}"><button type="button" id="orders-search-toggle" title="Поиск" aria-label="Поиск">${svgIcon('search',16)}</button><input id="orders-search" type="search" aria-label="Поиск заказа" placeholder="Школа, класс, заказчик" value="${esc(f.query)}"></label><div class="segmented" role="group" aria-label="Вид заказов"><button type="button" data-orders-view="grid" aria-label="Плитка" title="Плитка" aria-pressed="${view==='grid'}">${svgIcon('grid',16)}</button><button type="button" data-orders-view="board" aria-label="Канбан" title="Канбан" aria-pressed="${view==='board'}">${svgIcon('board',16)}</button></div><button class="primary" data-action="new-order">＋ Создать заказ</button></div></div><div class="registry-bar"><div class="segmented registry-scopes" role="group" aria-label="Какие заказы показать">${[['all','Все'],['active','В работе'],['waiting','Ждём класс'],['archive','Архив']].map(([k,label])=>`<button type="button" data-order-scope="${k}" aria-pressed="${f.scope===k}">${label}</button>`).join('')}</div><div class="registry-filters">${chip('school','school','Школа',schools,v=>f.school===v)}${chip('class','users','Класс',classes,v=>searchKey(f.className)===searchKey(v))}${chip('stage','stages','Этап',STAGES.map(([k,label,color])=>[k,label,color]),v=>f.stage===v)}<button type="button" class="filter-chip filter-toggle" id="filter-attention" aria-pressed="${f.attention}">${svgIcon('alert',15)}Требуют действий</button><button type="button" class="text-button registry-reset" id="orders-reset">Сбросить</button></div></div><div id="orders-items"></div></div>`;const input=$('#orders-search');$('#orders-search-toggle').onclick=()=>{input.parentElement.classList.add('open');input.focus();};input.oninput=()=>{f.query=input.value;drawOrders();};input.onblur=()=>{if(!input.value)input.parentElement.classList.remove('open');};input.onkeydown=e=>{if(e.key==='Escape'){input.value='';f.query='';input.blur();drawOrders();}};const keys={school:'school',class:'className',stage:'stage'};for(const [id,key] of Object.entries(keys))$('#filter-'+id).onchange=e=>{f[key]=e.target.value;drawOrders();};document.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{const select=$('#filter-'+b.dataset.clear);select.value='';f[keys[b.dataset.clear]]='';drawOrders();select.focus();});$('#filter-attention').onclick=e=>{f.attention=!f.attention;e.currentTarget.setAttribute('aria-pressed',String(f.attention));drawOrders();};$('#orders-reset').onclick=()=>{Object.assign(f,{query:'',school:'',className:'',stage:'',scope:'all',attention:false});history.replaceState(null,'','#orders');ordersPage();};document.querySelectorAll('[data-order-scope]').forEach(b=>b.onclick=()=>{f.scope=b.dataset.orderScope;document.querySelectorAll('[data-order-scope]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));drawOrders();});document.querySelectorAll('[data-orders-view]').forEach(b=>b.onclick=()=>{registryView=b.dataset.ordersView;try{localStorage.setItem('ordersView',registryView);}catch{}document.querySelectorAll('[data-orders-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));drawOrders();});drawOrders();}
function syncFilterBar(view){const f=orderFilters,board=view==='board';for(const [key,value] of [['school',f.school],['class',f.className],['stage',f.stage]]){const chip=$(`[data-chip="${key}"]`);if(!chip)continue;const select=chip.querySelector('select');chip.classList.toggle('set',!!value);chip.querySelector('.chip-label').textContent=select.selectedOptions[0]?.textContent||select.options[0].textContent;}const stageChip=$('[data-chip="stage"]');if(stageChip)stageChip.hidden=board;const active=[f.query,f.school,f.className,!board&&f.stage,f.scope!=='all',f.attention].filter(Boolean).length;const reset=$('#orders-reset');if(reset)reset.hidden=active<2;}
function drawOrders(){const el=$('#orders-items');if(!el)return;const params=new URLSearchParams();for(const [key,value] of Object.entries({q:orderFilters.query,school:orderFilters.school,class:orderFilters.className,stage:orderFilters.stage,scope:orderFilters.scope==='all'?'':orderFilters.scope,attention:orderFilters.attention?'1':''}))if(value)params.set(key,value);history.replaceState(null,'','#orders'+(params.size?'?'+params:''));const view=ordersView(),rows=registryOrders({ignoreStage:view==='board'});syncFilterBar(view);if(view==='board'){el.className='registry-board-wrap';let board=$('#board');if(!board){el.innerHTML='<div id="board"></div>';board=$('#board');enableBoardDragging(board);}const html=boardHtml(rows);if(board.renderedHtml!==html){board.innerHTML=html;board.renderedHtml=html;}el.renderedHtml='';OrderActivities.refreshCards();return;}el.className='registry-grid';if(!rows.length){el.renderedHtml='';el.innerHTML=`<div class="empty-state"><h3>${state.orders.length?'Заказы не найдены':'Заказов пока нет'}</h3><p>${state.orders.length?'Измените условия поиска или сбросьте фильтры.':'Создайте первый заказ, чтобы начать работу.'}</p></div>`;return;}const tiles=rows.map(o=>orderTile(o,cardStatus(o))).join('');if(el.renderedHtml!==tiles){el.innerHTML=tiles;el.renderedHtml=tiles;hydrateOrderPreviews(el);}OrderActivities.refreshCards();}
// Kanban: every working stage is a tray of order cards (the archive only on its own tab); an empty stage folds into a narrow strip.
// The column already names the stage, so a card shows only the school with the class and the same turn plate as the tiles; a filled stage tints its tray with its own colour, an empty one stays grey; trays are only as tall as their cards.
function boardHtml(rows){const archive=orderFilters.scope==='archive';return STAGES.filter(([k])=>archive?k==='archive':k!=='archive').map(([k,l,color])=>{const cards=rows.filter(o=>o.stage===k).map(o=>[o,cardStatus(o)]),mine=cards.filter(([,st])=>tileTurn(st)==='mine').length;return cards.length?`<section class="board-col" style="--stage:${color}"><a class="board-head" href="#stage/${k}">${stageRing(k,28)}<span class="board-title">${l}</span><small class="${mine?'has-mine':''}" title="${mine?`Ждут вас: ${mine}`:''}">${cards.length}</small></a><div class="board-rows">${cards.map(([o,st])=>boardCard(o,st)).join('')}</div></section>`:`<a class="board-strip" href="#stage/${k}" title="${l}">${stageRing(k,24,'#a9a6ae')}<span>${l}</span></a>`;}).join('');}

function enableBoardDragging(board){
  let startX=0,startScroll=0,pointerId=null,dragged=false,suppressClick=false;
  board.addEventListener('pointerdown',e=>{
    if(e.pointerType==='touch'||e.button!==0||board.scrollWidth<=board.clientWidth)return;
    pointerId=e.pointerId;startX=e.clientX;startScroll=board.scrollLeft;dragged=false;
  });
  board.addEventListener('pointermove',e=>{
    if(e.pointerId!==pointerId)return;
    if(!dragged&&Math.abs(e.clientX-startX)<6)return;
    if(!dragged){dragged=true;board.setPointerCapture(pointerId);board.classList.add('is-dragging');}
    board.scrollLeft=startScroll-(e.clientX-startX);
    e.preventDefault();
  });
  const finish=e=>{
    if(e.pointerId!==pointerId)return;
    if(dragged){suppressClick=true;setTimeout(()=>{suppressClick=false;},0);board.classList.remove('is-dragging');if(board.hasPointerCapture(pointerId))board.releasePointerCapture(pointerId);}
    pointerId=null;dragged=false;
  };
  board.addEventListener('pointerup',finish);
  board.addEventListener('pointercancel',finish);
  board.addEventListener('dragstart',e=>{if(pointerId!==null)e.preventDefault();});
  board.addEventListener('click',e=>{if(suppressClick){e.preventDefault();e.stopPropagation();suppressClick=false;}},true);
}
function boardCard(o,st){const turn=tileTurn(st);return `<article class="board-card"><a class="board-card-main" href="#order/${o.id}/${st.tab}" title="${esc(schoolLabel(o))} · ${esc(o.class_name)}"><span class="order-tile-heading"><strong class="order-tile-school">${esc(o.school)}</strong><span class="order-tile-separator" aria-hidden="true">·</span><strong class="order-tile-class">${esc(o.class_name)}</strong></span></a><div class="order-plate board-plate turn-${turn}"><span class="order-plate-text" title="${esc(st.note||st.text)}">${esc(st.note||st.text)}</span>${tileAction(o,st)}${st.progress?`<progress max="${st.progress[1]}" value="${st.progress[0]}" aria-label="${esc(st.text)}"></progress>`:''}</div>${OrderActivities.slot(o)}${orderMenu(o,'order-tile-menu board-card-menu')}</article>`;}
function queueView(){try{return localStorage.getItem('queueView')==='grid'?'grid':'list';}catch{return 'list';}}
// Queue rows wear the same turn colours as the tiles: yellow is the photographer's move, grey is someone else's, red needs attention.
// Stage list = a table: the row's width holds columns you compare down the list. A count shown in its own
