const QUEUE_PROGRESS={photos:'Обработка',forms:'Анкеты',approval:'Правки'};
function queueProgress(o,st){const c=o.client_progress;if(o.stage==='forms')return c?.enabled&&c.total?[c.completed,c.total]:null;if(o.stage==='approval')return o.corrections_total?[o.corrections_total-(o.corrections_open||0),o.corrections_total]:null;return st.progress?.[1]?st.progress:null;}
function queueHead(k){return `<div class="queue-table-head" aria-hidden="true"><span>Класс</span><span>Состояние</span>${QUEUE_PROGRESS[k]?`<span>${QUEUE_PROGRESS[k]}</span>`:''}<span>На этапе</span><span>Альбомов</span><span></span></div>`;}
function queueRow(o,st){const turn=tileTurn(st),d=daysIn(o),p=queueProgress(o,st),text=st.stale?'Стоит напомнить':p&&st.wait?st.wait:p&&o.corrections_open?'Правки от класса':st.text;return `<article class="queue-row turn-${turn}"><a class="queue-name" href="#order/${o.id}/${st.tab}">${stageRing(o.stage,28)}<span class="order-tile-heading" title="${esc(schoolLabel(o))} · ${esc(o.class_name)}"><strong class="order-tile-school">${esc(o.school)}</strong><span class="order-tile-separator" aria-hidden="true">·</span><strong class="order-tile-class">${esc(o.class_name)}</strong></span></a><div class="queue-state"><span class="queue-pill">${esc(text)}</span>${OrderActivities.slot(o)}</div>${QUEUE_PROGRESS[o.stage]?`<span class="queue-progress ${p&&p[0]>=p[1]?'full':''}">${p?`<span class="queue-bar"><i style="width:${Math.round(p[0]/p[1]*100)}%"></i></span><span>${p[0]} / ${p[1]}</span>`:''}</span>`:''}<span class="queue-num ${st.stale?'hot':''}">${d?count(d,'день','дня','дней'):'сегодня'}</span><span class="queue-num">${o.copies||''}</span><span class="queue-act">${tileAction(o,st,'queue-action'+(turn==='mine'?' is-ready':''))}</span></article>`;}
function orderPreview(o){const photos=(o.preview_photo_ids?.length?o.preview_photo_ids:[o.cover_id].filter(Boolean)).slice(0,3),grade=esc(o.class_name);if(!photos.length)return `<div class="order-preview order-preview-empty" aria-hidden="true"><span class="order-preview-paper"><small>${esc(o.school)}</small><strong>${grade}</strong><i></i></span></div>`;const images=photos.map(id=>`<img src="/media/${encodeURIComponent(id)}/thumb" alt="" loading="lazy" decoding="async">`).join('');return `<div class="order-preview ${o.layout_revision?'order-preview-has-layout':''}" aria-hidden="true" ${o.layout_revision?`data-layout-preview="${esc(o.id)}" data-revision="${esc(o.layout_revision)}"`:''}><span class="order-preview-fan count-${photos.length}">${images}</span></div>`;}
const orderLayoutPreviews=new Map();
function hydrateOrderPreviews(root){for(const host of root.querySelectorAll('[data-layout-preview]')){const id=host.dataset.layoutPreview,revision=host.dataset.revision,key=id+':'+revision;let request=orderLayoutPreviews.get(key);if(!request){request=api('/orders/'+encodeURIComponent(id)+'/layout').catch(()=>null);orderLayoutPreviews.set(key,request);}request.then(data=>{if(!data||!host.isConnected||host.dataset.revision!==revision)return;const doc=data.document,variant=doc?.variants?.[0],spread=variant&&layoutSpread(doc,variant.owner,0);if(!spread)return;host.innerHTML=`<div class="order-preview-book">${layoutCanvas(spread,doc,data.photos,false,false)}</div>`;host.classList.add('has-rendered-layout');});}}
// Tiles name the stage once and show one next step. The plate colour says only whose turn it is: yellow for the photographer,
// grey while the class, processing, printer or courier have it, red when something blocks the order or the class has gone quiet.
const STAGE_NOUNS={new:'Новый',photos:'Фото',forms:'Сбор данных',layout:'Макет',approval:'Согласование',print:'Печать',delivery:'Доставка',archive:'Архив'};
const tileTurn=st=>st.urgent||st.stale?'alert':isMine(st)?'mine':'wait';
// One stage mark everywhere: eight ring segments show how far the order has come, in the stage's own colour as on the kanban board;
