function stageRing(stage,size,color=stageOf(stage)[2]){const n=STAGES.length,at=STAGES.findIndex(x=>x[0]===stage)+1,c=size/2,w=Math.max(2.5,size/11),r=c-w/2-1,len=2*Math.PI*r,seg=len/n,gap=Math.max(1.5,size/22);return `<span class="stage-ring" style="width:${size}px;height:${size}px;--turn:${color}" aria-hidden="true"><svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}">${STAGES.map((_,k)=>`<circle cx="${c}" cy="${c}" r="${r.toFixed(2)}" class="${k<at?'on':''}" stroke-width="${w.toFixed(1)}" stroke-dasharray="${(seg-gap).toFixed(2)} ${len.toFixed(2)}" stroke-dashoffset="${(-k*seg).toFixed(2)}" transform="rotate(-90 ${c} ${c})"/>`).join('')}</svg>${svgIcon(STAGE_ICONS[stage],Math.round(size*.4))}</span>`;}
const stageNumber=o=>`Этап ${STAGES.findIndex(x=>x[0]===o.stage)+1} из ${STAGES.length} · ${STAGE_NOUNS[o.stage]}`;
function tileAction(o,st,cls='order-plate-action'){const [act,label]=st.action||[];if(!act)return '';return act==='review'||act==='layout'?`<a class="${cls}" href="#order/${o.id}/${st.tab}">${esc(label)} →</a>`:`<button type="button" class="${cls}" data-card-action="${act}" data-id="${o.id}" data-tab="${st.tab}">${esc(label)} →</button>`;}
