const TG_GLYPH='<path d="M21 4 3 11.2l5.8 2.1L17 8l-6.3 6.6L17 20Z"/><path d="M10.7 14.6 10 19l2.6-2.6"/>',WA_GLYPH='<path d="M3.8 20.2l1.2-4A8.8 8.8 0 1 1 8.1 19Z"/><path d="M9.1 8.4c.3-.3.7-.3.9 0l.7 1.5c.1.3 0 .6-.2.8l-.5.5a6 6 0 0 0 2.8 2.8l.5-.5c.2-.2.5-.3.8-.2l1.5.7c.3.2.3.6 0 .9-.6.7-1.5 1-2.4.7a8 8 0 0 1-4.7-4.7c-.3-.9 0-1.8.6-2.5Z"/>';
function phoneDigits(v){let d=String(v||'').replace(/\D/g,'');if(d.length===11&&d[0]==='8')d='7'+d.slice(1);else if(d.length===10&&d[0]==='9')d='7'+d;return d;}
function phoneReach(v){const d=phoneDigits(v),tel=d?'+'+d:'';const brand=(cls,href,title,glyph)=>`<a class="phone-reach-btn ${cls}" href="${href}" target="_blank" rel="noopener" title="${title}" aria-label="${title}"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${glyph}</svg></a>`;return `<span class="phone-reach"><button type="button" class="phone-reach-num" data-v2="copy" data-copy="${esc(v)}" title="Скопировать">${esc(v)}<span class="copy-mark">${svgIcon('copy',13)}</span></button>${d?`<span class="phone-reach-pop" role="group" aria-label="Связаться">${brand('tg',`https://t.me/${esc(tel)}`,'Написать в Telegram',TG_GLYPH)}${brand('wa',`https://wa.me/${esc(d)}`,'Написать в WhatsApp',WA_GLYPH)}<a class="phone-reach-btn call" href="tel:${esc(tel)}" title="Позвонить" aria-label="Позвонить">${svgIcon('phone',14)}</a></span>`:''}</span>`;}
function orderMeta(o){const phone=o.customer_contact?phoneReach(o.customer_contact):'',who=[esc(o.customer_name||''),phone].filter(Boolean).join(' · ');return [['pin',o.school_city],['calendar',o.graduation_year&&`Выпуск ${o.graduation_year}`],['layout',[count(o.copies,'альбом','альбома','альбомов'),orderPackage(o)].filter(Boolean).join(' · ')],['user',who,true]].filter(x=>x[1]).map(([icon,text,html])=>`<span>${svgIcon(icon,14)}${html?text:esc(text)}</span>`).join('');}
function stagePathHtml(o){const at=STAGES.findIndex(x=>x[0]===o.stage),d=daysIn(o);return `<ol class="stage-path-list" ${state.stagePath?'':'hidden'}>${STAGES.map(([k,,color],n)=>`<li style="--stage:${color}" class="${n<at?'done':n===at?'current':''}"><i></i>${STAGE_NOUNS[k]}${n===at?`<small>сейчас${d?' · '+count(d,'день','дня','дней'):''}</small>`:''}</li>`).join('')}</ol>`;}
function syncSummary(o){const el=$('#order-status');if(!el)return;const st=cardStatus(o),step=st.stale&&!o.layout_queue?staleStep(o):stageStep(o);const html=`<div class="order-head-top"><div class="stage-path"><button type="button" class="stage-path-toggle" data-v2="stage-path" aria-expanded="${!!state.stagePath}" title="Путь заказа" aria-label="Путь заказа: ${esc(stageNumber(o))}">${stageRing(o.stage,56)}</button>${stagePathHtml(o)}</div><div class="order-head-info"><span class="order-head-stage">${esc(stageNumber(o))}</span><h1>${esc(o.school)} · ${esc(o.class_name)}</h1><div class="order-head-meta">${orderMeta(o)}</div></div>${orderMenu(o,'order-head-menu')}</div>${o.client_progress?.enabled&&o.stage!=='forms'&&state.view==='client'?clientProgress(o):''}<div class="order-plate order-head-plate turn-${step.turn||tileTurn(st)}"><div class="order-plate-body"><span class="order-plate-title">${esc(step.title)}</span>${step.text?`<p>${esc(step.text)}</p>`:''}${step.progress?`<progress max="${step.progress[1]}" value="${step.progress[0]}"></progress>`:''}${step.extra||''}</div><div class="step-actions">${step.actions||''}</div></div>${OrderActivities.html(o)}`;if(el.renderedHtml!==html){OrderActivities.morph(el,html);el.renderedHtml=html;}}
document.addEventListener('click',e=>{if(!state.stagePath||e.target.closest('.stage-path'))return;state.stagePath=false;const o=state.order;if(o)syncSummary(o);});
