const svgIcon=(name,size=14)=>`<svg class="ico ico-${name}" viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]}</svg>`;
// After the forms or the layout go to the class, two weeks of silence turn the order red: time to remind them.
const STALE_DAYS=14;
function cardStatus(o){const st=stageStatus(o),d=daysIn(o);return st.kind==='waiting'&&['forms','approval'].includes(o.stage)&&d>=STALE_DAYS?{...st,stale:true,note:`Стоит напомнить · ${count(d,'день','дня','дней')}`}:st;}
function stageStatus(o){const s=stats(o),c=o.client_progress;switch(o.stage){case'new':return {text:'Нет фотографий',kind:'todo',icon:'upload',tab:'photos',action:['add-photos','Загрузить фото']};case'photos':return s.pending?{text:`Обработано ${s.total-s.pending} из ${s.total}`,kind:'working',icon:'loader',progress:[s.total-s.pending,s.total],tab:'photos',wait:'Ждём обработку'}:s.review?{text:`${s.review} фото на проверку`,kind:'todo',icon:'alert',tab:'review',action:['review','Проверить фото']}:{text:'Фото готовы',kind:'done',icon:'check',tab:'photos',action:['send-forms','Отправить анкеты']};case'forms':return c?.status==='complete'?{text:'Все заполнили',kind:'done',icon:'check',tab:'client',action:['make-layout','Создать макет']}:{text:c?.enabled&&c.total?`Заполнили ${c.completed} из ${c.total}`:'Ждём класс',kind:'waiting',icon:'clock',progress:c?.enabled&&c.total?[c.completed,c.total]:null,tab:'client',wait:'Ждём класс'};case'layout':return {text:'Макет готов к проверке',note:'Готов к проверке',kind:'todo',icon:'layout',tab:'layout',action:['layout','Открыть макет']};case'approval':return o.approved?{text:'Согласовано',kind:'done',icon:'check',tab:'layout',action:['allow-production','В печать']}:o.corrections_open?{text:`Правки · осталось ${o.corrections_open}`,kind:'todo',icon:'alert',urgent:true,tab:'layout',action:['layout','Открыть макет']}:o.corrections_total?{text:'Правки исправлены',kind:'todo',icon:'check',tab:'layout',action:['layout','Открыть макет']}:{text:'Макет у класса',kind:'waiting',icon:'clock',tab:'layout',wait:'Ждём согласования'};case'print':return {text:'В печати',kind:'working',icon:'print',tab:'client',action:['stage-delivery','Передано в доставку']};case'delivery':return {text:'В доставке',kind:'working',icon:'truck',tab:'client',action:['stage-archive','В архив']};default:return {text:'Заказ завершён',kind:'waiting',icon:'archive',tab:'client',wait:'В архиве'};}}
function nav(){const hash=location.hash.slice(1)||'orders',active=state.order?'stage/'+state.order.stage:hash.startsWith('schools')?'schools':hash.split('?')[0];const link=(href,key,inner)=>`<a href="${href}" class="${active===key?'active':''}" ${active===key?'aria-current="page"':''}>${inner}</a>`;$('#v2-nav').innerHTML=link('#orders','orders',`${svgIcon('list',18)}<span>Все заказы</span>` )+'<div class="nav-caption">Этапы</div>'+STAGES.map(([k,l])=>{const list=state.orders.filter(o=>o.stage===k),mine=list.filter(o=>isMine(cardStatus(o))).length;return link('#stage/'+k,'stage/'+k,`${svgIcon(STAGE_ICONS[k],18)}<span>${l}</span>${mine?`<small class="nav-mine" title="Ждут вас">${mine}</small>`:list.length?`<small>${list.length}</small>`:''}`);}).join('')+'<div class="nav-sep"></div>'+link('#masters','masters',`${svgIcon('templates',18)}<span>Мастер-макеты</span>`)+link('#schools','schools',`${svgIcon('school',18)}<span>Каталог школ</span>`);}
function closeDesignMenus(){document.querySelectorAll('.design-menu.open').forEach(m=>{m.classList.remove('open');m.querySelector('.design-menu-list').hidden=true;m.querySelector('.design-menu-toggle').setAttribute('aria-expanded','false');});}
