async function renderSettings(){
  const version=routeVersion;
  $('#main').innerHTML='<div class="page account-settings"><p class="muted">Загружаем настройки…</p></div>';
  try{
    const profile=await api('/profile');
    if(version!==routeVersion)return;
    const modes=['personal','shipping','both'].includes(profile.delivery_modes)?profile.delivery_modes:'both';
    $('#main').innerHTML=`<div class="page account-settings">
      <div class="settings-intro">
        <span class="settings-intro-label">Аккаунт</span>
        <h1>Настройки студии</h1>
        <p>Выберите правила, которые будут действовать для новых заказов.</p>
      </div>
      <form id="profile-form" class="settings-card">
        <h2>Настройки аккаунта</h2>
        <section class="settings-section" aria-labelledby="settings-album-title">
          <h3 id="settings-album-title">Альбом</h3>
          <label class="settings-row settings-toggle-row">
            <span class="settings-row-icon">${icon('print')}</span>
            <span class="settings-row-copy"><strong>Подарочный альбом учителю</strong><small>Добавлять один подарочный экземпляр в новый заказ</small></span>
            <input type="checkbox" name="teacher_gift" class="settings-toggle" ${profile.teacher_gift?'checked':''}>
          </label>
        </section>
        <section class="settings-section" aria-labelledby="settings-delivery-title">
          <h3 id="settings-delivery-title">Получение</h3>
          <label class="settings-row settings-select-row" for="settings-delivery-modes">
            <span class="settings-row-icon">${icon('delivery')}</span>
            <span class="settings-row-copy"><strong>Способы получения</strong><small>Доступные варианты в новом заказе</small></span>
            <select id="settings-delivery-modes" name="delivery_modes" aria-label="Получение в новом заказе"><option value="both" ${modes==='both'?'selected':''}>Лично или отправка</option><option value="personal" ${modes==='personal'?'selected':''}>Только лично</option><option value="shipping" ${modes==='shipping'?'selected':''}>Только отправка</option></select>
          </label>
        </section>
        <p class="settings-note">Уже созданные заказы сохраняют прежние правила. Печать запускается только после вашего отдельного разрешения.</p>
        <p id="profile-error" class="error" role="alert"></p>
        <button class="primary settings-save" type="submit">Сохранить настройки</button>
      </form>
    </div>`;
    $('#profile-form').onsubmit=async event=>{
      event.preventDefault();
      const button=event.target.querySelector('[type=submit]');
      button.disabled=true;
      $('#profile-error').textContent='';
      const data=new FormData(event.target);
      try{
        await api('/profile',json('PUT',{teacher_gift:data.get('teacher_gift')==='on',delivery_modes:String(data.get('delivery_modes')||'both')}));
        toast('Сохранено. Правила применятся к новым заказам.');
      }catch(error){$('#profile-error').textContent=error.message;}
      finally{button.disabled=false;}
    };
  }catch(error){
    if(version===routeVersion)$('#main').innerHTML=`<div class="page account-settings"><h1>Настройки</h1><p class="error">${esc(error.message)}</p><button class="secondary" id="retry-settings">Повторить</button></div>`;
    const retry=$('#retry-settings');if(retry)retry.onclick=()=>renderSettings();
  }
}
