const fieldBase=new WeakMap();
function dialogFields(dialog){return [...dialog.querySelectorAll('input,textarea,select')].filter(el=>!el.dataset.photo&&!['button','submit','reset','hidden','image'].includes(el.type));}
function readField(el){if(el.type==='file')return [...el.files].map(f=>`${f.name}:${f.size}:${f.lastModified}`).join('|');if(el.type==='checkbox'||el.type==='radio')return el.checked?'1':'0';return el.value;}
function rememberDialog(dialog){for(const el of dialogFields(dialog))fieldBase.set(el,readField(el));}
function baselineNewFields(dialog){for(const el of dialogFields(dialog))if(!fieldBase.has(el))fieldBase.set(el,readField(el));}
function dialogDirty(dialog){return dialogFields(dialog).some(el=>fieldBase.has(el)&&fieldBase.get(el)!==readField(el));}
function placeDiscard(dialog,warn){const anchor=dialog.querySelector('.dialog-heading .close'),box=(anchor||dialog).getBoundingClientRect(),width=warn.offsetWidth;warn.style.top=(anchor?box.bottom+8:box.top+16)+'px';warn.style.left=Math.max(8,Math.min(innerWidth-width-8,anchor?box.right-width:box.left+(box.width-width)/2))+'px';}
function showDiscard(dialog){let warn=dialog.querySelector('.discard-warn');if(!warn){warn=document.createElement('div');warn.className='discard-warn';warn.setAttribute('role','alertdialog');warn.setAttribute('aria-label','Закрыть без сохранения?');warn.innerHTML=`<p><strong>Закрыть без сохранения?</strong><span>Введённые данные пропадут.</span></p><button type="button" data-discard="stay">${svgIcon('check',16)}<span>Продолжить заполнение</span></button><button type="button" class="danger" data-discard="close">${svgIcon('alert',16)}<span>Закрыть и не сохранять</span></button>`;dialog.append(warn);warn.querySelector('[data-discard="stay"]').onclick=()=>warn.remove();warn.querySelector('[data-discard="close"]').onclick=()=>dialog.close();}placeDiscard(dialog,warn);warn.querySelector('[data-discard="stay"]').focus();}
function dismissDialog(dialog){if(!dialog?.open)return;if(dialogDirty(dialog))showDiscard(dialog);else dialog.close();}
function backdropDialog(e){const dialog=e.target instanceof HTMLDialogElement?e.target:null;if(!dialog?.open)return null;const rect=dialog.getBoundingClientRect();return e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom?dialog:null;}
function watchDialog(dialog){if(dialog.dataset.dismissWatch)return;dialog.dataset.dismissWatch='1';new MutationObserver(()=>{if(dialog.open)baselineNewFields(dialog);}).observe(dialog,{childList:true,subtree:true});}
document.querySelectorAll('dialog').forEach(watchDialog);
new MutationObserver(list=>{for(const m of list)for(const n of m.addedNodes)if(n.nodeType===1){if(n.matches?.('dialog'))watchDialog(n);n.querySelectorAll?.('dialog').forEach(watchDialog);}}).observe(document.body,{childList:true,subtree:true});
document.addEventListener('toggle',e=>{const dialog=e.target;if(!(dialog instanceof HTMLDialogElement)||e.newState!=='open')return;dialog.querySelector('.discard-warn')?.remove();rememberDialog(dialog);},true);
document.addEventListener('close',e=>{if(e.target instanceof HTMLDialogElement){e.target.querySelector('.discard-warn')?.remove();if(e.target.id==='action-dialog')e.target.classList.remove('wide-dialog');}},true);
document.addEventListener('cancel',e=>{const dialog=e.target;if(!(dialog instanceof HTMLDialogElement))return;const warn=dialog.querySelector('.discard-warn');if(warn){e.preventDefault();warn.remove();dialog.querySelector('.dialog-heading .close')?.focus();return;}if(!dialogDirty(dialog))return;e.preventDefault();showDiscard(dialog);},true);
document.addEventListener('pointerdown',e=>{const warn=document.querySelector('dialog[open] .discard-warn');if(warn&&!warn.contains(e.target)&&!e.target.closest?.('[data-close]')&&!backdropDialog(e))warn.remove();},true);
addEventListener('resize',()=>{const warn=document.querySelector('dialog[open] .discard-warn');if(warn)placeDiscard(warn.closest('dialog'),warn);});
let backdropDown=null;
document.addEventListener('pointerdown',e=>{backdropDown=backdropDialog(e);},true);
document.addEventListener('pointerup',e=>{const dialog=backdropDown;backdropDown=null;if(!dialog?.open)return;const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dismissDialog(dialog);},true);
const INLINE_STAGE={'stage-delivery':['delivery','Заказ передан в доставку'],'stage-archive':['archive','Заказ перенесён в архив']};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-card-action]');if(!b)return;const inline=INLINE_STAGE[b.dataset.cardAction];if(inline){b.disabled=true;try{await api(`/orders/${b.dataset.id}/stage`,json('POST',{stage:inline[0]}));toast(inline[1]);await route();}catch(error){b.disabled=false;toast(error.message);}return;}state.pendingAction={id:b.dataset.id,action:b.dataset.cardAction};const hash=`#order/${b.dataset.id}/${b.dataset.tab}`;if(location.hash===hash)route();else location.hash=hash;});
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action],[data-order],[data-close],[data-tab],[data-person]');if(!target)return;if(target.dataset.order){location.hash='order/'+target.dataset.order;return;}if(target.dataset.close){dismissDialog($('#'+target.dataset.close));return;}if(target.dataset.tab){state.tab=target.dataset.tab;state.selected.clear();renderGroups();return;}if(target.dataset.person){showPerson(target.dataset.person);return;}switch(target.dataset.action){case'new-order':openNew();break;case'move':openMove();break;case'retry':try{await api(`/orders/${state.order.id}/retry${state.view==='photos'&&state.shootId?'?shoot_id='+encodeURIComponent(state.shootId):''}`,json('POST',{}));toast('Обработка запущена повторно');startOrderPolling();await refreshOrder();}catch(e){toast(e.message);}break;}});
document.addEventListener('change',e=>{if(e.target.dataset.photo){if(e.target.checked)state.selected.add(e.target.dataset.photo);else state.selected.delete(e.target.dataset.photo);PhotoTools.changed();}});
$('#order-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;$('#form-error').textContent='';const values=Object.fromEntries(new FormData(e.target));if(!values.school.trim()||!values.school_city.trim()){$('#form-error').textContent='Укажите школу и город.';$('#order-school input')?.focus();button.disabled=false;return;}if(!values.school_id)delete values.school_id;values.graduation_year=Number(values.graduation_year);values.copies=Number(values.copies);if(!values.master_template_id)delete values.master_template_id;try{const result=await api('/orders',json('POST',values));$('#order-dialog').close();location.hash='order/'+result.id;toast('Заказ создан. Когда съёмка пройдёт, загрузите фотографии.');}catch(error){$('#form-error').textContent=error.message;}finally{button.disabled=false;}};
$('#move-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api(`/orders/${state.order.id}/move`,json('POST',{photo_ids:[...state.selected],person_id:new FormData(e.target).get('target')||null}));$('#move-dialog').close();$('#person-dialog').close();state.selected.clear();await refreshOrder();toast('Фотографии перенесены');}catch(error){toast(error.message);}finally{button.disabled=false;}};
window.addEventListener('hashchange',()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());route();});window.addEventListener('beforeunload',e=>{if(state.uploading){e.preventDefault();e.returnValue='';}});route();
document.addEventListener('click',async e=>{
  const t=e.target.closest('[data-v2],[data-photo-filter]');if(!t)return;
  if(t.dataset.photoFilter){state.photoFilter=t.dataset.photoFilter;state.selected.clear();renderWorkspace();return;}
  const action=t.dataset.v2;
  try{
    if(action==='copy'){await copyText(t.dataset.copy??t.closest('.message-card')?.querySelector('.message-text')?.textContent??'');flashCopied(t);if(t.dataset.sent)markSent(t.dataset.sent);}
    if(action==='edit-forms-contact'){state.contactEditing=true;renderFormsContact();$('#forms-contact-name')?.focus();}
    if(action==='cancel-forms-contact'){state.contactEditing=false;renderFormsContact();}
    if(action==='edit-template'){state.editingTemplate=t.dataset.kind;renderFormsAccess();$(`#template-${t.dataset.kind}`)?.focus();}
    if(action==='cancel-template'){state.editingTemplate=null;renderFormsAccess();}
    if(action==='save-template'||action==='default-template'){const kind=t.dataset.kind,body=action==='save-template'?$(`#template-${kind}`).value:'';state.templates[kind]={...state.templates[kind],...await api('/message-templates/'+kind,json('PUT',{body}))};state.editingTemplate=null;renderFormsAccess();toast(action==='save-template'?'Шаблон сохранён':'Вернули стандартный текст');}
    if(action==='open-corrections')await openCorrections();
    if(action==='remind')await remindClass();
    if(OrderActivities.ACTIONS.includes(action))await OrderActivities.action(action);
    if(action==='reset-codes'){confirmStep('Выдать новые коды?','Старые коды перестанут работать, всем придётся войти заново. Ссылка останется прежней.','Выдать новые',async()=>{const id=state.order.id;setClientLink(id,await api(`/orders/${id}/client-codes/reset`,json('POST',{})));$('#action-dialog').close();renderFormsAccess();toast('Новые коды выданы');});}
    if(action==='send-forms'){const s=stats(state.order);confirmStep('Отправить анкеты классу?',`${s.review?s.review+' фото ещё не проверены. ':''}${s.pending?'Часть фотографий ещё обрабатывается. ':''}Появится ссылка для класса и два кода: код входа для всех и код управления для ответственного. Ссылку, коды и готовые сообщения всегда можно открыть во вкладке «Сбор данных».`,'Отправить',async()=>{const id=state.order.id;const [link]=await Promise.all([api(`/orders/${id}/client-link`,json('POST',{})),loadTemplates()]);setClientLink(id,link);$('#action-content').innerHTML=`<div class="dialog-heading"><h2>Анкеты открыты</h2><button class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div><p class="muted">Скопируйте сообщения и отправьте их классу и ответственному.</p><div class="forms-sent">${accessHtml(state.order)}${messagesHtml(state.order,false)}</div><div class="dialog-actions"><button class="primary" data-close="action-dialog">Готово</button></div>`;renderFormsAccess();await refreshOrder();});}
    if(action==='make-layout')await chooseOrderMaster();
    if(action==='cancel-layout-queue'||action==='build-queued-now')await LayoutStart.action(action);
    if(action==='confirm-step'){t.disabled=true;try{await state.confirmRun();if($('[data-v2="confirm-step"]'))$('#action-dialog').close();}catch(error){$('#step-error').textContent=error.message;}finally{t.disabled=false;}}
    if(action==='stage-delivery'||action==='stage-archive'){await api(`/orders/${state.order.id}/stage`,json('POST',{stage:action.slice(6)}));await refreshOrder();}
    if(action==='publish-layout')confirmStep('Отправить макет на согласование?','Класс увидит макет по своей ссылке. Ответственный согласует его вместе с количеством альбомов и получением.','Отправить',async()=>{await api(`/orders/${state.order.id}/layout/publish`,json('POST',{}));await refreshOrder();toast('Макет отправлен классу');});
    if(action==='allow-production'||action==='force-production'){const force=action==='force-production',id=state.order.id;const [deal,published]=await Promise.all([api(`/orders/${id}/deal`),api(`/orders/${id}/layout/publication`)]);const choices=published.document.variants||[],needsGift=(deal.allocations||[]).some(r=>r.key==='gift'&&(r.paid+r.gift)>0)&&!choices.some(v=>v.owner==='teacher_variant');confirmStep(force?'Отправить в печать без согласования?':'Отправить в печать?',(force?'Класс ещё не согласовал макет — ответственность за содержание остаётся на вас. ':'')+'Будут подготовлены файлы для печати. После этого макет больше не редактируется.','В печать',async()=>{const gift_owner=$('#production-gift-owner')?.value;if(needsGift&&!gift_owner)throw new Error('Выберите альбом для подарка учителю');await api(`/orders/${id}/production`,json('POST',{responsibility:force,gift_owner:gift_owner||null}));await refreshOrder();toast('Заказ отправлен в печать');});if(needsGift)$('#step-error').insertAdjacentHTML('beforebegin',`<label>Альбом для подарка учителю<select id="production-gift-owner"><option value="">Выберите опубликованный вариант</option>${choices.map(v=>`<option value="${esc(v.owner)}">${esc(v.name||v.owner)}</option>`).join('')}</select></label><p class="muted small">Отдельного учительского варианта нет. Выбранный альбом будет добавлен в подарочный тираж.</p>`);}
    if(action==='tile-edit-order'||action==='tile-delete-order'){closeDesignMenus();state.menuOrder=state.order?.id===t.dataset.id?state.order:state.orders.find(o=>o.id===t.dataset.id);if(!state.menuOrder)return;if(action==='tile-edit-order')editOrderForm();else confirmRemoval('order');}
    if(action==='stage-path'){state.stagePath=!state.stagePath;syncSummary(state.order);}
    if(action==='close-actions')$('#action-dialog').close();
    if(action==='delete-photos')confirmRemoval('photos');
    if(action==='add-photos')openShootDialog();
    if(action==='new-shoot')openShootDialog(null,true);
    if(action==='design-menu'){const menu=t.closest('.design-menu'),open=!menu.classList.contains('open');closeDesignMenus();if(open){menu.classList.add('open');t.setAttribute('aria-expanded','true');menu.querySelector('.design-menu-list').hidden=false;menu.querySelector('[role=menuitem]').focus();}}
    if(action==='duplicate-design'){closeDesignMenus();t.disabled=true;try{const copy=await api(`/designs/${t.dataset.id}/duplicate`,json('POST',{}));await mastersPage();toast(`Создали копию «${copy.name}»`);}finally{t.disabled=false;}}
    if(action==='delete-design'){closeDesignMenus();const d=(state.designs||[]).find(x=>x.id===t.dataset.id);if(!d)return;const n=d.packages.length;confirmStep(`Удалить «${d.name}»?`,`Удалятся все комплектации дизайна (${n}) и сохранённые блоки. Заказы, в которых этот дизайн уже выбран, сохранят свою копию макета.`,'Удалить',async()=>{await api('/designs/'+d.id,{method:'DELETE'});$('#action-dialog').close();await mastersPage();toast(`Дизайн «${d.name}» удалён`);});}
    if(action==='new-design'){$('#design-form').reset();resetPicked($('#design-form'));$('#design-form .error').textContent='';$('#design-dialog').showModal();}
    if(action==='new-package'){const d=(state.designs||[]).find(x=>x.id===t.dataset.id);if(!d)return;state.packageDesign=d;$('#package-form').reset();$('#package-form .error').textContent='';$('#package-form select').innerHTML=d.packages.map(p=>`<option value="${esc(p.template_id)}">${esc(p.name)}</option>`).join('');$('#package-dialog').showModal();}
    if(action==='queue-view'){try{localStorage.setItem('queueView',t.dataset.view);}catch{}document.querySelectorAll('[data-v2="queue-view"]').forEach(b=>b.setAttribute('aria-pressed',String(b===t)));drawQueue($('.queue').dataset.stage);}
    if(action==='queue-search'){t.parentElement.classList.add('open');$('#queue-search').focus();}
    if(action==='open-shoot'||action==='close-shoot'||action==='open-teachers'){state.shootId=action==='open-teachers'?'teachers':action==='open-shoot'?t.dataset.id:null;state.photoFilter='all';state.selected.clear();renderWorkspace();}
    if(action==='edit-shoot'){closeDesignMenus();editShoot(t.dataset.id);}
    if(action==='cancel-shoot-edit')stopShootEdit();
    if(action==='delete-shoot'){closeDesignMenus();confirmRemoval('shoot',t.dataset.id);}
    if(action==='select-visible')PhotoTools.selectAll();
    if(action==='set-cover'){if(state.selected.size!==1){toast('Выберите одну фотографию для обложки');return;}await api(`/orders/${state.order.id}/cover`,json('PUT',{photo_ids:[...state.selected]}));toast('Обложка заказа обновлена');}
    if(action==='confirm-photos'){const photos=state.order.photos.filter(p=>state.selected.has(p.id)&&canConfirmMatch(p));if(!photos.length){toast('Выберите совпадения с указанной персоной');return;}t.disabled=true;try{await api(`/orders/${state.order.id}/confirm-photos`,json('POST',{photo_ids:photos.map(p=>p.id),expected_persons:Object.fromEntries(photos.map(p=>[p.id,p.person_id]))}));photos.forEach(p=>state.selected.delete(p.id));await refreshOrder();if($('#person-dialog').open)showPerson(state.person);else if(state.view==='photos')renderWorkspace();else renderGroups();toast(`Подтверждено: ${photos.length}. Остальные снимки можно распределить вручную.`);}finally{syncConfirmation();}}
    if(action==='confirm-delete'){
      const r=state.removal;
      t.disabled=true;
      try{if(r.kind==='shoot')await api(`/orders/${r.orderId}/shoots/${r.shootId}`,{method:'DELETE'});else await api(`/orders/${r.orderId}`+(r.kind==='photos'?'/delete-photos':''),r.kind==='photos'?json('POST',{photo_ids:r.ids}):{method:'DELETE'});$('#action-dialog').close();$('#person-dialog').close();state.selected.clear();if(r.kind==='order'){if(location.hash.startsWith('#order/'))location.hash='home';else await route();toast('Заказ удалён');}else{if(r.kind==='shoot')state.shootId=null;await refreshOrder();if(state.view==='photos')renderWorkspace();toast(r.kind==='shoot'?'Съёмка удалена':'Фотографии удалены');}}catch(error){$('#delete-error').textContent=error.message;}finally{t.disabled=false;}
    }
  }catch(error){toast(error.message);}
});

// The class's corrections live in a dialog: the head plate only counts them, however many there are.
async function openCorrections(){const id=state.order.id,list=await api(`/orders/${id}/corrections?all=true`);if(state.order?.id!==id)return;const date=v=>new Date(v).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}),what=c=>c.kind==='name'?'Имя':c.spread_label+(c.variant?' · '+c.variant:''),text=c=>[c.kind==='name'?`${c.old_name} → ${c.new_name}`:'',c.comment].filter(Boolean).join(' · ');
  $('#action-content').innerHTML=`<div class="dialog-heading"><h2>Правки от класса</h2><button type="button" class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div><ul class="fix-list">${list.map(c=>`<li class="${c.status==='open'?'':'fixed'}"><label><input type="checkbox" data-fix="${esc(c.id)}" ${c.status==='open'?'':'checked'}><span class="fix-body"><strong>${esc(what(c))}</strong>${text(c)?`<span>${esc(text(c))}</span>`:''}<small>${esc(date(c.created_at))}</small></span></label></li>`).join('')}</ul><div class="fix-foot"><a class="secondary" href="#order/${id}/layout">Открыть макет</a><button type="button" class="primary" data-close="action-dialog">Готово</button></div>`;
  $('#action-content .fix-list').onchange=async e=>{const box=e.target.closest('[data-fix]');if(!box)return;box.disabled=true;try{await api(`/orders/${id}/corrections/${encodeURIComponent(box.dataset.fix)}/${box.checked?'resolve':'reopen'}`,json('POST',{}));box.closest('li').classList.toggle('fixed',box.checked);await refreshOrder();}catch(err){box.checked=!box.checked;toast(err.message);}finally{box.disabled=false;}};
  const d=$('#action-dialog');if(!d.open)d.showModal();}
async function remindClass(){const o=state.order;let p=currentLink();if(!p){setClientLink(o.id,await api(`/orders/${o.id}/client-link`));p=currentLink();}if(!p?.url){toast('Ссылка для класса ещё не создана');return;}
  await copyText(o.stage==='forms'?reminderText(o,p):`Напоминаем про макет альбома ${o.class_name}: он ждёт согласования.\nСсылка: ${p.url}${p.entry_pin?`\nКод входа: ${p.entry_pin}`:''}`);toast('Текст напоминания скопирован');}
// A class silent for STALE_DAYS keeps the stage wording and gets the reminder as the move.
function staleStep(o){const c=o.client_progress,d=count(daysIn(o),'день','дня','дней'),a=(tab,label)=>state.view===tab?'':`<a class="secondary" href="#order/${o.id}/${tab}">${label}</a>`,remind='<button class="primary" data-v2="remind">Напомнить</button>';
  return o.stage==='forms'?{title:'Класс заполняет анкеты',text:`${c.completed} из ${c.total} · ${d} без движения`,progress:[c.completed,c.total||1],actions:a('client','Ссылка и коды')+remind}:{title:'Макет у класса',text:`${d} без ответа`,actions:a('layout','Открыть макет')+remind};}
function clientProgress(o,details=false){const c=o.client_progress;if(!c)return '';if(!c.enabled)return details?'<p class="muted">Клиентский кабинет ещё не открыт.</p>':'';return `<div class="client-fill ${c.status==='complete'?'complete':''}"><div><strong>${esc(c.label)}</strong><span>Заполнено ${c.completed} из ${c.total}</span></div><progress max="${c.total||1}" value="${c.completed}" aria-label="Заполнено участников: ${c.completed} из ${c.total}"></progress>${details&&c.status!=='complete'?`<p class="muted small">${c.total?`Осталось: ${c.remaining}. Анкета считается заполненной, когда выбран портрет и указаны имя и фамилия.`:'Ожидаем появления участников.'}</p>`:''}</div>`;}

function matchReference(p){return state.order.photos.find(f=>f.person_id===p.person_id&&f.id!==p.id&&f.status==='ready'&&!f.uncertain)||state.order.photos.find(f=>f.person_id===p.person_id&&f.id!==p.id&&f.status==='ready');}
function canConfirmMatch(p){return p.status==='ready'&&!!p.person_id&&!!matchReference(p);}
function matchCaption(p){if(!p.person_id)return '<div class="match-target unmatched">Персона не определена — назначьте вручную</div>';const index=state.order.persons.findIndex(x=>x.id===p.person_id);if(index<0)return '';const person=state.order.persons[index],reference=matchReference(p);return `<div class="match-target">${reference?`<img src="/media/${reference.id}/thumb" alt="Сравнить с ${esc(personName(person,index))}" loading="lazy">`:''}<span><small>${p.uncertain?'Предположительно':'Назначено'}</small><strong>${esc(personName(person,index))}</strong>${!reference?'<small>Нет другого снимка для сравнения</small>':reference.uncertain?'<small>Образец тоже требует проверки</small>':''}</span></div>`;}
function syncConfirmation(){if(!state.order)return;const photos=state.order.photos.filter(p=>state.selected.has(p.id)&&canConfirmMatch(p));const people=[...new Set(photos.map(p=>p.person_id))];const label=people.length===1?personName(state.order.persons.find(p=>p.id===people[0]),state.order.persons.findIndex(p=>p.id===people[0])):null;document.querySelectorAll('[data-v2="confirm-photos"]').forEach(b=>{b.disabled=!photos.length;b.innerHTML=`${svgIcon('ok',17)}<span>${photos.length?`Подтвердить ${label?esc(label)+' · ':''}${photos.length}`:'Подтвердить'}</span>`;b.title=photos.length?'Подтвердить показанные персоны · Enter':'Среди выбранных нет снимков с предложенной персоной';});}

function shootStatus(shoot){const photos=state.order.photos.filter(p=>p.shoot_id===shoot.id),pending=photos.filter(p=>['pending','processing'].includes(p.status)).length,review=photos.filter(needsReview).length;return pending?`<small class="shoot-status">Обработка · ${pending}</small>`:review?`<small class="shoot-status">Проверить · ${review}</small>`:'';}
function openShootDialog(files=null,startNew=false){
  const orderId=state.order.id,shoots=state.order.shoots||[],active=shoots.find(s=>s.id===state.shootId)||shoots.find(s=>s.kind==='portrait');
  $('#action-content').innerHTML=`<form id="shoot-form"><div class="dialog-heading"><h2>Загрузить фотографии</h2><button type="button" class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div>${shoots.length?`<label>Куда загрузить<select name="destination">${shoots.map(s=>`<option value="${s.id}" ${!startNew&&s.id===active?.id?'selected':''}>${esc(s.title)} · ${s.kind==='portrait'?'Портретная':'Общая'}</option>`).join('')}<option value="teachers" ${!startNew&&state.shootId==='teachers'?'selected':''}>Учителя · портреты в каталог школы</option><option value="new" ${startNew?'selected':''}>＋ Новая съёмка</option></select></label>`:''}<div id="new-shoot-fields"><div class="shoot-field"><span class="shoot-field-head">Тип съёмки<span class="help-dot" id="shoot-kind-hint" tabindex="0" aria-label="Подсказка">i</span></span><select name="kind" aria-label="Тип съёмки"><option value="portrait">Портретная</option><option value="general">Общая</option><option value="teachers">Учителя</option></select></div><div class="shoot-row"><label>Название<input name="title" maxlength="100" placeholder="Портреты, Прогулка…" value="Портреты" required></label><label>Дата съёмки<input name="shot_on" type="date"></label></div></div><div class="shoot-drop" id="shoot-drop"><input name="photos" type="file" accept="image/jpeg,image/png,.jpg,.jpeg,.png" multiple hidden><input name="folder" type="file" webkitdirectory multiple hidden>${svgIcon('upload',26)}<p class="shoot-drop-text">Перетащите <button type="button" data-pick="photos">фото</button> или <button type="button" data-pick="folder">папку</button> сюда</p><small id="shoot-drop-count"></small></div><p id="shoot-error" class="error" role="alert"></p><div class="dialog-actions"><button type="button" class="secondary" data-close="action-dialog">Отмена</button><button type="submit" class="primary">Загрузить</button></div></form>`;
  const form=$('#shoot-form'),destination=form.elements.destination,fields=$('#new-shoot-fields');
  const teachersChosen=()=>destination?.value==='teachers'||((!destination||destination.value==='new')&&form.elements.kind.value==='teachers');
  const update=()=>{const isNew=!destination||destination.value==='new',teachers=teachersChosen();fields.hidden=!isNew;form.elements.title.required=isNew&&!teachers;form.querySelector('.shoot-row').hidden=teachers;form.querySelector('[type=submit]').textContent=teachers?'Загрузить учителям':'Загрузить';$('#shoot-kind-hint').dataset.help=teachers?'Фото попадают в каталог школы — подпишите каждого учителя, и портрет появится во всех заказах школы':'Портреты раскладываются по ученикам, общие снимки подбираются в макет';};
  if(destination)destination.onchange=update;update();
  let chosen=files||[];const picked=()=>chosen,drop=$('#shoot-drop');
  const guess=()=>PhotoTools.guessDate(picked()).then(d=>{if(d&&!form.elements.shot_on.value)form.elements.shot_on.value=d;});
  const choose=list=>{if(!list.length)return;chosen=list;$('#shoot-error').textContent='';showChosen();guess();};
  const showChosen=()=>{if(!drop)return;drop.classList.toggle('filled',chosen.length>0);$('#shoot-drop-count').textContent=chosen.length?`Выбрано фото: ${chosen.length}`:'';};
  if(drop){showChosen();if(files)guess();
    for(const input of [form.elements.photos,form.elements.folder])input.onchange=()=>{choose(PhotoTools.onlyImages([...input.files]));input.value='';};
    drop.onclick=e=>{if(e.target.matches('input'))return;const b=e.target.closest('[data-pick]');(b?form.elements[b.dataset.pick]:form.elements.photos).click();};
    drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging');};
    drop.ondragleave=e=>{if(!drop.contains(e.relatedTarget))drop.classList.remove('dragging');};
    drop.ondrop=async e=>{e.preventDefault();drop.classList.remove('dragging');choose(PhotoTools.onlyImages(await PhotoTools.filesFrom(e.dataTransfer)));};}
  form.elements.kind.onchange=()=>{if(['Портреты','Общая съёмка'].includes(form.elements.title.value))form.elements.title.value=form.elements.kind.value==='general'?'Общая съёмка':'Портреты';update();};
  form.onsubmit=async e=>{e.preventDefault();const selected=picked();if(!selected.length){$('#shoot-error').textContent='Выберите фотографии или папку';return;}if(teachersChosen()){if(!state.order.school_id){$('#shoot-error').textContent='Выберите школу заказа из каталога: «⋯ → Изменить заказ».';return;}state.shootId='teachers';$('#action-dialog').close();if(state.view!=='photos')location.hash=`order/${orderId}/photos`;else renderWorkspace();SchoolCatalog.upload(state.order.school_id,selected,orderId);return;}const submit=form.querySelector('[type=submit]');submit.disabled=true;try{let id=destination?.value;if(!id||id==='new'){const result=await api(`/orders/${orderId}/shoots`,json('POST',{kind:form.elements.kind.value,title:form.elements.title.value.trim(),shot_on:form.elements.shot_on.value}));id=result.id;}await refreshOrder();state.shootId=id;state.selected.clear();state.photoFilter='all';$('#action-dialog').close();if(state.view!=='photos'){location.hash=`order/${orderId}/photos`;}else renderWorkspace();await uploadFiles(selected);}catch(error){$('#shoot-error').textContent=error.message;}finally{submit.disabled=false;}};
  $('#action-dialog').showModal();
}

function safeHref(url){const v=String(url||'');return v.startsWith('/')||v.startsWith('https://')||v.startsWith('http://')?v:'#';}
function setClientLink(orderId,link){state.clientLink={orderId,...link,url:link.url?new URL(link.url,location.origin).href:null};}
function currentLink(){const p=state.clientLink;return p&&p.orderId===state.order?.id?p:null;}
async function loadTemplates(){if(!state.templates)state.templates=await api('/message-templates');return state.templates;}
function fillTemplate(body,o,p){const values={'{школа}':o.school,'{класс}':o.class_name,'{заказчик}':o.customer_name||'','{обращение}':o.customer_name?', '+o.customer_name.trim():'','{ссылка}':p?.url||'—','{код_входа}':p?.entry_pin||'—','{код_управления}':p?.manage_pin||'—'};return String(body||'').replace(/\{(школа|класс|заказчик|обращение|ссылка|код_входа|код_управления)\}/g,m=>values[m]);}
function copyRow(label,value,hint=''){return `<button type="button" class="copy-row" data-v2="copy" data-copy="${esc(value)}" title="Нажмите, чтобы скопировать"><span class="copy-label">${esc(label)}${hint?`<small>${esc(hint)}</small>`:''}</span><span class="copy-value">${esc(value)}</span><span class="copy-mark" aria-hidden="true">Копировать</span></button>`;}
function accessHtml(o){const p=currentLink();if(!p?.url)return '';const codes=p.entry_pin&&p.manage_pin?`<div class="access-code-grid"><div class="access-code"><span class="access-code-title">${svgIcon('user',18)} Для всего класса</span>${copyRow('Код входа',p.entry_pin,'Отправьте в общий чат')}</div><div class="access-code private"><span class="access-code-title">${svgIcon('approve',18)} Только ответственному</span>${copyRow('Код управления',p.manage_pin,'Отправьте лично')}</div></div>`:`<div class="codes-lost"><p>Коды этого заказа не сохранились. Выдайте новые, чтобы подготовить сообщения.</p><button class="secondary" data-v2="reset-codes">Выдать новые коды</button></div>`;return `<div class="access-link"><div><strong>Ссылка на анкету</strong><small>Одна ссылка для класса и ответственного</small></div>${copyRow('Ссылка',p.url)}<a class="access-open" href="${esc(safeHref(p.url))}" target="_blank" rel="noopener noreferrer" aria-label="Открыть анкету в новой вкладке">↗</a></div>${codes}`;}
function messagesHtml(o,editable=true){const p=currentLink(),tpl=state.templates;if(!p?.url||!p.entry_pin||!p.manage_pin||!tpl)return '';const cards=[['class','В общий чат','Класс · ссылка и код входа'],['manager','Лично ответственному',o.customer_name||'Контакт не указан']].map(([kind,title,sub])=>{const item=tpl[kind];if(!item)return '';if(editable&&state.editingTemplate===kind)return `<div class="message-card editing"><div class="message-head"><div><strong>${title}</strong><small>Шаблон для всех заказов</small></div></div><textarea id="template-${kind}" rows="9" maxlength="2000">${esc(item.body)}</textarea><p class="muted small">Подставляются: {класс}, {школа}, {ссылка}, {код_входа}, {код_управления}, {заказчик}, {обращение}. Последнее добавляет запятую и ФИО, если контакт указан.</p><div class="message-actions">${item.custom?`<button class="text-button" data-v2="default-template" data-kind="${kind}">Вернуть стандартный</button>`:''}<button class="secondary" data-v2="cancel-template">Отмена</button><button class="primary" data-v2="save-template" data-kind="${kind}">Сохранить</button></div></div>`;return `<div class="message-card ${kind}"><div class="message-head"><span class="message-icon">${svgIcon(kind==='class'?'user':'approve',19)}</span><div><strong>${title}</strong><small>${esc(sub)}</small></div></div><div class="message-text">${esc(fillTemplate(item.body,o,p))}</div><div class="message-actions">${editable?`<button class="text-button" data-v2="edit-template" data-kind="${kind}">Изменить шаблон</button>`:''}<button class="primary" data-v2="copy">${svgIcon('copy',16)} Скопировать текст</button></div></div>`;}).join('');return `<div class="message-cards">${cards}</div>`;}
function initials(name){return String(name||'').trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase();}
function formsContactHtml(o){if(state.contactEditing)return `<form id="forms-contact-form" class="forms-contact-form"><div class="forms-contact-form-fields"><label>Фамилия, имя, отчество<input id="forms-contact-name" name="customer_name" maxlength="100" autocomplete="name" placeholder="Петрова Ирина Ивановна" value="${esc(o.customer_name||'')}"></label><label>Телефон<input name="customer_contact" type="tel" inputmode="tel" maxlength="40" autocomplete="tel" placeholder="+7 999 000-00-00" value="${esc(o.customer_contact||'')}"></label></div><p class="forms-contact-error error" role="alert"></p><div class="forms-contact-actions"><button type="button" class="secondary" data-v2="cancel-forms-contact">Отмена</button><button type="submit" class="primary">Сохранить контакт</button></div></form>`;const phone=o.customer_contact?.trim(),name=o.customer_name?.trim();return `<div class="fk-person"><span class="fk-avatar${name?' named':''}">${name?esc(initials(name)):svgIcon('user',20)}</span><div class="fk-person-info"><strong>${name?esc(name):'Укажите ответственного'}</strong>${phone?`<a href="tel:${esc(phone.replace(/[^\d+]/g,''))}">${svgIcon('phone',13)} ${esc(phone)}</a>`:'<span class="fk-missing">Телефон не указан</span>'}</div><div class="fk-tools">${phone?`<button class="fk-tool" data-v2="copy" data-copy="${esc(phone)}" title="Скопировать телефон" aria-label="Скопировать телефон"><span class="copy-mark">${svgIcon('copy',16)}</span></button>`:''}<button class="fk-tool" data-v2="edit-forms-contact" title="${name||phone?'Изменить контакт':'Добавить контакт'}" aria-label="Изменить контакт">${svgIcon('edit',16)}</button></div></div>`;}
function renderFormsContact(){const el=$('#forms-contact');if(el&&state.order)el.innerHTML=formsContactHtml(state.order);}
function pinTiles(pin,label,icon=''){return `<button type="button" class="fk-pin" data-v2="copy" data-copy="${esc(pin)}" title="Скопировать код" aria-label="${esc(label)} ${esc(pin)}, скопировать"><span class="fk-pin-label copy-mark"><span class="lbl">${icon}${esc(label)}</span><span class="act">Копировать</span></span><span class="fk-digits">${[...String(pin)].map(d=>`<i>${esc(d)}</i>`).join('')}</span></button>`;}
function formsPinHtml(kind,p){const pin=kind==='class'?p?.entry_pin:p?.manage_pin;if(!p?.url||!pin)return '';return kind==='class'?pinTiles(pin,'Код входа'):pinTiles(pin,'Код управления',svgIcon('lock',12));}
function formsRecipientHtml(kind,o,p){const tpl=state.templates?.[kind];if(!p?.url)return `<div class="fk-ghost" aria-hidden="true"><i></i><i></i><i></i></div>`;const pin=kind==='class'?p.entry_pin:p.manage_pin;if(!pin||!tpl)return `<div class="codes-lost"><p>Коды этого заказа не сохранились.</p><button class="secondary" data-v2="reset-codes">Выдать новые коды</button></div>`;if(state.editingTemplate===kind)return `<div class="fk-editor"><textarea id="template-${kind}" rows="9" maxlength="2000">${esc(tpl.body)}</textarea><p class="muted small">{класс} {школа} {ссылка} {код_входа} {код_управления} {заказчик} {обращение}</p><div class="fk-foot">${tpl.custom?`<button class="text-button" data-v2="default-template" data-kind="${kind}">Вернуть стандартный</button>`:''}<button class="secondary" data-v2="cancel-template">Отмена</button><button class="primary" data-v2="save-template" data-kind="${kind}">Сохранить</button></div></div>`;const text=fillTemplate(tpl.body,o,p);return `<div class="fk-bubble">${esc(text)}</div><div class="fk-foot"><button class="text-button" data-v2="edit-template" data-kind="${kind}">Изменить текст</button><span class="fk-sent" data-kind="${kind}">${sentLabel(p,kind)}</span><button class="primary fk-send" data-v2="copy" data-sent="${kind}" data-copy="${esc(text)}">${svgIcon('copy',16)}<span class="copy-mark">Скопировать сообщение</span></button></div>`;}
function formsPanelHtml(o){return `<div class="forms-panel fk"><section class="fk-card fk-link" id="forms-access"><p class="muted small">Загружаем…</p></section><div class="fk-recipients"><section class="fk-card fk-class"><header class="fk-rhead"><span class="fk-rtile">${svgIcon('users',22)}</span><div><span class="fk-when">В общий чат</span><strong>Класс ${esc(o.class_name)}</strong></div><div class="fk-pinslot" id="forms-pin-class"></div></header><div id="forms-class"></div></section><section class="fk-card fk-mgr"><header class="fk-rhead"><span class="fk-rtile">${svgIcon('approve',22)}</span><div><span class="fk-when">Лично</span><strong>Ответственный</strong></div><div class="fk-pinslot" id="forms-pin-manager"></div></header><div id="forms-contact">${formsContactHtml(o)}</div><div id="forms-manager"></div></section></div><section class="fk-card fk-progress" id="forms-progress" hidden></section><section class="fk-card fk-teachers"><h3>${svgIcon('school',18)} Выбор учителей</h3><div id="order-teachers"></div></section><section class="fk-card fk-deal" id="forms-deal" hidden><h3>Решения класса</h3><div id="mvp-deal"><p class="muted small">Загружаем…</p></div></section></div>`;}
function sentLabel(p,kind){const at=p?.sent?.[kind];return at?`${svgIcon('check',14)} Скопировано ${new Date(at).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}`:'';}
async function markSent(kind){const id=state.order?.id;if(!id)return;try{const link=await api(`/orders/${id}/client-sent/${kind}`,json('POST',{}));if(state.order?.id!==id)return;setClientLink(id,link);const el=document.querySelector(`.fk-sent[data-kind="${kind}"]`);if(el)el.innerHTML=sentLabel(currentLink(),kind);}catch{}}
function reminderText(o,p){const c=o.client_progress;return `Напоминаем про анкеты для альбома ${o.class_name}: осталось заполнить ${c.remaining} из ${c.total}.\nСсылка: ${p.url}\nКод входа: ${p.entry_pin}`;}
function renderFormsProgress(){const box=$('#forms-progress');if(!box||!state.order)return;const o=state.order,c=o.client_progress,p=currentLink(),people=o.client_people||[];if(!c?.enabled||!c.total){box.hidden=true;return;}box.hidden=false;const done=people.filter(x=>x.done),wait=people.filter(x=>!x.done),all=[...wait,...done],complete=c.total&&c.completed===c.total;const tile=x=>`<figure class="fk-face ${x.done?'done':''}">${x.photo_id?`<img src="/media/${esc(x.photo_id)}/thumb" alt="" loading="lazy">`:'<span class="fk-noface">'+svgIcon('user',22)+'</span>'}${x.done?`<i class="fk-tick">${svgIcon('check',12)}</i>`:''}<figcaption>${x.done?esc(x.name):'&nbsp;'}</figcaption></figure>`;box.innerHTML=`<div class="fk-progress-head"><div><span class="fk-when">Анкеты детей</span><strong>${complete?'Все заполнили':`Заполнено ${c.completed} из ${c.total}`}</strong></div>${!complete&&p?.entry_pin&&c.total?`<button class="secondary fk-remind" data-v2="copy" data-copy="${esc(reminderText(o,p))}">${svgIcon('copy',15)}<span class="copy-mark">Скопировать напоминание</span></button>`:''}</div><progress max="${c.total||1}" value="${c.completed}" aria-label="Заполнено ${c.completed} из ${c.total}"></progress>${all.length?`<div class="fk-faces">${all.map(tile).join('')}</div>`:'<p class="muted small">Участников пока нет.</p>'}`;}
function renderFormsAccess(){const box=$('#forms-access');if(!box||!state.order)return;const o=state.order,p=currentLink();if(!p?.url){box.innerHTML=`<div class="fk-empty"><span class="fk-link-tile">${svgIcon('link',22)}</span><div><strong>Анкеты ещё не отправлены</strong><small>Ссылка и коды появятся после отправки</small></div>${['new','photos'].includes(o.stage)?'<button class="primary" data-v2="send-forms">Отправить на анкеты</button>':''}</div>`;}else box.innerHTML=`<span class="fk-link-tile">${svgIcon('link',22)}</span><div class="fk-link-main"><span class="fk-when">Ссылка на анкету</span><button type="button" class="fk-url" data-v2="copy" data-copy="${esc(p.url)}"><span class="fk-url-text">${esc(p.url)}</span><span class="fk-url-copy copy-mark">${svgIcon('copy',15)} Копировать</span></button></div><div class="fk-tools"><a class="fk-tool" href="${esc(safeHref(p.url))}" target="_blank" rel="noopener noreferrer" title="Открыть анкету" aria-label="Открыть анкету в новой вкладке">↗</a>${p.entry_pin&&p.manage_pin?'<button class="fk-tool" data-v2="reset-codes" title="Выдать новые коды" aria-label="Выдать новые коды">↻</button>':''}</div>`;const c=$('#forms-class'),m=$('#forms-manager');for(const k of ['class','manager']){const slot=$('#forms-pin-'+k);if(slot)slot.innerHTML=formsPinHtml(k,p);}if(c)c.innerHTML=formsRecipientHtml('class',o,p);if(m)m.innerHTML=formsRecipientHtml('manager',o,p);renderFormsProgress();const deal=$('#forms-deal');if(deal)deal.hidden=!p?.url;}
document.addEventListener('submit',async e=>{if(e.target.id!=='forms-contact-form')return;e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]'),values=Object.fromEntries(new FormData(form));button.disabled=true;form.querySelector('.forms-contact-error').textContent='';try{await api(`/orders/${state.order.id}`,json('PATCH',values));state.contactEditing=false;await refreshOrder();renderFormsContact();renderFormsAccess();toast('Контакт обновлён');}catch(error){form.querySelector('.forms-contact-error').textContent=error.message;button.disabled=false;}});
async function loadFormsAccess(){const id=state.order?.id;if(!id)return;try{const [link]=await Promise.all([api(`/orders/${id}/client-link`),loadTemplates()]);if(state.order?.id!==id)return;setClientLink(id,link);renderFormsAccess();}catch(error){if($('#forms-access')&&state.order?.id===id)$('#forms-access').innerHTML=`<p class="error">${esc(error.message)}</p>`;}}
async function copyText(text){try{await navigator.clipboard.writeText(text);}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();document.execCommand('copy');area.remove();}}
function flashCopied(el){el.classList.add('copied');clearTimeout(el.copyTimer);if(el.classList.contains('fk-tool')){el.copyTimer=setTimeout(()=>el.classList.remove('copied'),1400);return;}const mark=el.querySelector('.copy-mark')||el;if(el.copyLabel==null)el.copyLabel=mark.innerHTML;mark.textContent='Скопировано';el.copyTimer=setTimeout(()=>{el.classList.remove('copied');mark.innerHTML=el.copyLabel;},1400);}
function productionOn(p){if(!p)return false;if(p===true)return true;if(typeof p==='string')return !['','none','pending','waiting'].includes(p);if(typeof p==='object')return !!(p.authorized||p.at||p.allowed||p.status==='authorized'||p.status==='done');return false;}
function present(v){if(v==null||v==='')return '—';if(typeof v==='boolean')return v?'да':'нет';if(typeof v==='number'||typeof v==='string')return String(v);if(Array.isArray(v)){if(!v.length)return '—';if(v[0]&&(v[0].label||v[0].key||v[0].name))return v.map(a=>`${a.label||a.name||a.key}: ${a.paid??0} платн.${a.gift?` / ${a.gift} под.`:''}`).join('; ');return v.map(present).join('; ');}if(typeof v==='object'){if('mode' in v||'address' in v||'recipient' in v){const mode=v.mode==='personal'?'лично':v.mode==='shipping'?'отправка':v.mode||'';return [mode,v.carrier,v.address,v.recipient,v.phone].filter(Boolean).join(', ')||'—';}const bits=Object.entries(v).filter(([,val])=>val!=null&&val!=='').map(([k,val])=>`${k}: ${present(val)}`);return bits.join('; ')||'—';}return String(v);}
function exportHtml(files,error){if(error)return `<p class="error">${esc(error)}</p>`;if(!files)return '';const base=`/api/orders/${encodeURIComponent(state.order.id)}/export`,list=(files.files||[]).map(f=>`<li>${esc(f.label||f.name)} · платных ${esc(f.copies_paid)} · подарочных ${esc(f.copies_gift)} · <a href="${base}/files/${encodeURIComponent(f.name)}">PDF</a> · <a href="${base}/files/${encodeURIComponent(f.jpeg_name)}">JPEG</a></li>`).join('');return `<div id="mvp-export"><h3>Файлы для печати</h3>${list?`<a class="primary" href="${base}/download">Скачать весь комплект</a><ul class="mvp-files">${list}</ul>`:'<p class="muted small">Файлов нет.</p>'}<p>Всего: ${esc(files.total)}</p><p class="muted small">RGB/sRGB. Перед печатью согласуйте с типографией формат, вылеты и цветовой профиль.</p></div>`;}
function dealHtml(d,files,fileError){const price=typeof d.offer_price==='number'?money(d.offer_price):present(d.offer_price);const date=v=>v?new Date(v).toLocaleDateString('ru-RU'):'';const groups=new Map();for(const a of d.allocations||[]){const label=a.label||a.name||a.key,key=`${label}|${a.paid??0}|${a.gift||0}`;groups.set(key,{label,paid:a.paid??0,gift:a.gift||0,n:(groups.get(key)?.n||0)+1});}const split=[...groups.values()].map(g=>`${g.label}${g.n>1?` ×${g.n}`:''}: ${g.paid} платн.${g.gift?` + ${g.gift} в подарок`:''}`).join(', ');const modes=d.delivery_modes==='personal'?'лично':d.delivery_modes==='shipping'?'отправка':'лично или отправка';const rows=[['Цена',price],['Тираж',`${d.planned_paid} платных${d.gift?` + ${d.gift} в подарок`:''}`],['Распределение',split],['Получение',d.delivery?present(d.delivery):modes],['Согласовано',d.approval?date(d.approval.at):''],['В печати',d.production?date(d.production.at):''],['Изменения',d.differences?.paid_copies?`платных было ${d.differences.paid_copies.was}, стало ${d.differences.paid_copies.now}`:''],['Данные удалятся',date(d.retention?.delete_on)]].filter(([,v])=>v);return `<dl>${rows.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${exportHtml(files,fileError)}`;}
async function loadMvpDeal(){const el=$('#mvp-deal');if(!el||!state.order)return;const id=state.order.id;el.innerHTML='<p class="muted small">Загружаем сводку…</p>';try{const deal=await api('/orders/'+encodeURIComponent(id)+'/deal');if(state.order?.id!==id||!$('#mvp-deal'))return;let files=null,fileError='';if(productionOn(deal.production)){try{files=await api('/orders/'+encodeURIComponent(id)+'/export');}catch(error){fileError=error.message;}}if(state.order?.id!==id||!$('#mvp-deal'))return;$('#mvp-deal').innerHTML=dealHtml(deal,files,fileError);}catch(error){if($('#mvp-deal')&&state.order?.id===id)$('#mvp-deal').innerHTML=`<p class="error">${esc(error.message)}</p>`;}}

/* InDesign import: the IDML and its fonts become the new design's first package; the report says what to check. */
const fileData=file=>new Promise((ok,fail)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>fail(Error('Не удалось прочитать '+file.name));r.readAsDataURL(file);});
async function fontData(file){const bytes=new Uint8Array(await file.slice(0,4).arrayBuffer()),otf=bytes[0]===0x4f&&bytes[1]===0x54&&bytes[2]===0x54&&bytes[3]===0x4f,url=await fileData(file);return {name:file.name.replace(/\.(ttf|otf)$/i,''),dataUrl:url.replace(/^data:[^;]*;/,`data:font/${otf?'otf':'ttf'};`)};}
async function importIdml(form){const idml=form.idml.files[0];if(!idml)return null;const fonts=await Promise.all([...form.fonts.files].slice(0,12).map(fontData));return api('/master-templates/import-idml',json('POST',{file:await fileData(idml),fonts}));}
function showImportReport(report,templateId){const items=[...report.items].sort((a,b)=>(a.level==='warning'?0:1)-(b.level==='warning'?0:1));$('#action-content').innerHTML=`<div class="dialog-heading"><h2>Макет перенесён</h2><button class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div><p class="muted">${report.summary.spreads} разворотов → ${report.summary.blocks} блоков, страница ${report.summary.page_size.join(' × ')} мм.</p><ul class="import-report">${items.map(i=>`<li class="${i.level}">${esc(i.text)}</li>`).join('')}</ul><button type="button" class="primary wide" data-open-editor>Открыть редактор</button>`;$('#action-content [data-open-editor]').onclick=()=>{location.href='/static/master-editor.html?id='+encodeURIComponent(templateId);};$('#action-dialog').showModal();}
/* File fields look like the other inputs: the box shows the chosen file (or how many) instead of the native button. */
function showPicked(input){const box=input.parentElement.querySelector('.file-box'),files=[...input.files];box.textContent=!files.length?box.dataset.empty:files.length===1?files[0].name:`${files.length} ${files.length<5?'файла':'файлов'}: ${files.map(f=>f.name.replace(/\.(ttf|otf)$/i,'')).join(', ')}`;box.classList.toggle('picked',files.length>0);box.title=files.map(f=>f.name).join('\n');}
function resetPicked(form){form.querySelectorAll('.idml-drop input').forEach(showPicked);form.querySelector('[data-idml-fonts]').hidden=true;}
$('#design-form').idml.onchange=e=>{const file=e.target.files[0],form=e.target.form;showPicked(e.target);form.querySelector('[data-idml-fonts]').hidden=!file&&!form.fonts.files.length;if(file&&!form.name.value.trim())form.name.value=file.name.replace(/\.idml$/i,'').slice(0,80);};
$('#design-form').fonts.onchange=e=>showPicked(e.target);
/* The import note sits over the dialog, above or below the «?» — wherever the screen has room — so the dialog never clips it. */
function placeHelp(dot){const help=dot.nextElementSibling,field=dot.closest('.idml-field').getBoundingClientRect(),at=dot.getBoundingClientRect(),gap=8,margin=12;help.style.left=field.left+'px';help.style.width=field.width+'px';help.style.maxHeight='';const height=help.scrollHeight,above=at.top-gap-margin,below=innerHeight-at.bottom-gap-margin,up=height<=above||above>=below;help.style.maxHeight=Math.max(120,up?above:below)+'px';help.style.top=(up?Math.max(margin,at.top-gap-Math.min(height,above)):at.bottom+gap)+'px';}
document.querySelectorAll('#design-form .help-dot').forEach(dot=>{dot.addEventListener('mouseenter',()=>placeHelp(dot));dot.addEventListener('focus',()=>placeHelp(dot));});
/* Drop zones: a dropped IDML goes to its field, dropped TTF/OTF to the fonts field, whichever zone gets them. */
function takeFiles(input,files){const dt=new DataTransfer();files.forEach(f=>dt.items.add(f));input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}));}
document.querySelectorAll('#design-form .idml-drop').forEach(zone=>{zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');const form=zone.closest('form'),files=[...e.dataTransfer.files],idml=files.find(f=>/\.idml$/i.test(f.name)),fonts=files.filter(f=>/\.(ttf|otf)$/i.test(f.name));if(!idml&&!fonts.length){form.querySelector('.error').textContent='Нужен файл IDML или шрифты TTF/OTF';return;}form.querySelector('.error').textContent='';if(idml)takeFiles(form.idml,[idml]);if(fonts.length)takeFiles(form.fonts,[...form.fonts.files,...fonts].slice(0,12));});});
for(const [form,isDesign] of [['#design-form',true],['#package-form',false]])$(form).onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]'),values=Object.fromEntries(new FormData(f));delete values.idml;delete values.fonts;values.price=Number(values.price);b.disabled=true;try{const imported=isDesign?await importIdml(f):null;if(isDesign)values.document=imported?imported.document:MasterDefaults.create();const d=await api(isDesign?'/designs':`/designs/${state.packageDesign.id}/packages`,json('POST',values));const id=isDesign?d.packages[0].template_id:d.template_id;if(imported){$('#design-dialog').close();b.disabled=false;showImportReport(imported.report,id);return;}location.href='/static/master-editor.html?id='+encodeURIComponent(id);}catch(error){f.querySelector('.error').textContent=error.message;b.disabled=false;}};
